function b64ToBytes(b64) {
  const bin = atob(b64); const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json" } });
}
function baseUrl(host) {
  let b = String(host || "").trim().replace(/\/+$/, "");
  if (!/^https?:\/\//i.test(b)) b = "https://" + b;
  const u = new URL(b);
  if (!/\/v\d/.test(u.pathname)) b += "/v1";
  return b;
}

async function proxy(req, path) {
  if (!ALLOWED.includes(path)) return json({ error: { message: "Not allowed" } }, 403);
  const host = req.headers.get("x-host"), key = req.headers.get("x-key");
  if (!host || !key) return json({ error: { message: "Missing host or API key" } }, 400);
  let target;
  try { target = baseUrl(host) + path; } catch { return json({ error: { message: "Invalid host" } }, 400); }
  const headers = { authorization: "Bearer " + key, "x-api-key": key, "HTTP-Referer": new URL(req.url).origin, "X-Title": "US4 AI" };
  const ct = req.headers.get("content-type");
  if (ct) headers["content-type"] = ct;
  try {
    const r = await fetch(target, {
      method: req.method,
      headers,
      body: req.method === "GET" || req.method === "HEAD" ? undefined : await req.arrayBuffer()
    });
    return new Response(r.body, {
      status: r.status,
      headers: { "content-type": r.headers.get("content-type") || "application/json", "cache-control": "no-store" }
    });
  } catch (e) {
    return json({ error: { message: "Host unreachable: " + (e && e.message || e) } }, 502);
  }
}

async function fetchImage(url) {
  const u = url.searchParams.get("url") || "";
  if (!/^https?:\/\//i.test(u)) return json({ error: "bad url" }, 400);
  try {
    const r = await fetch(u);
    const ct = r.headers.get("content-type") || "";
    if (!r.ok || !(ct.startsWith("image/") || ct.includes("octet-stream"))) return json({ error: "not an image" }, 415);
    return new Response(r.body, { headers: { "content-type": ct.startsWith("image/") ? ct : "image/png", "cache-control": "no-store" } });
  } catch { return json({ error: "fetch failed" }, 502); }
}

export default {
  async fetch(req) {
    const url = new URL(req.url);
    const p = url.pathname;
    if (p === "/" || p === "/index.html")
      return new Response(HTML, { headers: { "content-type": "text/html;charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff" } });
    if (p.startsWith("/api/")) return proxy(req, p.slice(4));
    if (p === "/fetch-image") return fetchImage(url);
    if (p === "/manifest.json" || p === "/manifest.webmanifest")
      return new Response(MANIFEST, { headers: { "content-type": "application/manifest+json", "cache-control": "public,max-age=86400" } });
    if (p === "/icon.svg")
      return new Response(ICON_SVG, { headers: { "content-type": "image/svg+xml", "cache-control": "public,max-age=604800" } });
    const m = p.match(/^\/(?:icon-(180|192|512)\.png|apple-touch-icon(?:-precomposed)?\.png|favicon\.ico)$/);
    if (m) {
      const size = m[1] || (p.startsWith("/apple") ? 180 : 192);
      return new Response(b64ToBytes(PNG[size]), { headers: { "content-type": "image/png", "cache-control": "public,max-age=604800" } });
    }
    return new Response("Not found", { status: 404 });
  }
};
